501	      const saved = await firstValueFrom(this.http.post<Person>(url, null));
502	      if (this.session.sheetId() !== sheet) return;
503	      this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
504	    } catch {
505	      this.rowError.set({
506	        id: person.id,
507	        message: `${person.name} could not be ${person.held ? 'taken off hold' : 'put on hold'}.`,
508	      });
509	    }
510	  }
511	
512	  protected claimsOf(personId: number): Claim[] {
513	    return this.claimsByPerson().get(personId) ?? [];
514	  }
515	
516	  /** A person's OPEN and SETTLED claims; drafts and voided claims do not count. */
517	  private countedOf(personId: number): Claim[] {
518	    return this.countedByPerson().get(personId) ?? [];
519	  }
520	
521	  protected claimedBy(personId: number): string {
522	    return money(this.countedOf(personId).reduce((sum, c) => sum + cents(c.amount), 0));
523	  }
524	
525	  /** The grade in force on the sheet's today among a person's grades. */
526	  protected gradeOf(person: Person): string {
527	    const today = this.session.today();
528	    return (today === null ? null : gradeOn(person.grades, today)) ?? person.grade;
529	  }
530	
531	  /** The sum of the dues shown on a person's claims that count, or n/a when the grade in force on
532	   *  the sheet's today has no rate in force then and no claim of theirs shows a figure. */
533	  protected dueBy(person: Person): string {
534	    const due = this.dueCentsBy(person);
535	    return due === null ? NO_RATE : money(due);
536	  }
537	
538	  private dueCentsBy(person: Person): number | null {
539	    const floor = this.floor();
540	    const late = this.late();
541	    const dues = this.countedOf(person.id).map((c) =>
542	      claimDueCents(c, this.rates.ofGradeOn(person.grades, c.date), floor, late),
543	    );
544	    if (!this.rates.current().has(this.gradeOf(person)) && dues.every((due) => due === null)) {
545	      return null;
546	    }
547	    return dues.reduce<number>((sum, due) => sum + (due ?? 0), 0);
548	  }
549	
550	  protected overdueOf(personId: number): Claim[] {
551	    return this.overdueByPerson().get(personId) ?? [];
552	  }
553	
554	  /** The dues of a person's overdue claims that count added up (a claim with no figure adds nothing). */
555	  protected overdueTotalOf(person: Person): string {
556	    return money(this.overdueCentsOf(person));
557	  }
558	
559	  private overdueCentsOf(person: Person): number {
560	    const floor = this.floor();
561	    const late = this.late();
562	    return this.overdueOf(person.id).reduce(
563	      (sum, c) => sum + (claimDueCents(c, this.rates.ofGradeOn(person.grades, c.date), floor, late) ?? 0),
564	      0,
565	    );
566	  }
567	
568	  /** A claim added (listed first) or saved in place. */
569	  protected claimSaved(saved: Claim): void {
570	    this.claims.update((list) =>
571	      list.some((c) => c.id === saved.id)
572	        ? list.map((c) => (c.id === saved.id ? saved : c))
573	        : [saved, ...list],
574	    );
575	  }
576	
577	  /** Take a statement for a person: their row and claims then show what it recorded and bound. */
578	  protected async takeStatement(person: Person): Promise<void> {
579	    this.rowError.set(null);
580	    const sheet = this.session.sheetId();
581	    if (!sheet) return;
582	    const url = `/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/statement`;
583	    try {
584	      const taken = await firstValueFrom(this.http.post<StatementTaken>(url, null));
585	      if (this.session.sheetId() !== sheet) return;
586	      const bound = new Map(taken.claims.map((c) => [c.id, c]));
587	      this.claims.update((list) => [
588	        ...taken.claims.filter((c) => !list.some((had) => had.id === c.id)),
589	        ...list.map((c) => bound.get(c.id) ?? c),
590	      ].sort((a, b) => b.id - a.id));
591	      const { count, lastDueTotal, lastDate } = taken.statements;
592	      this.people.update((list) =>
593	        list.map((p) =>
594	          p.id === person.id
595	            ? { ...p, statementCount: count, statedTotal: lastDueTotal, statementDate: lastDate }
596	            : p,
597	        ),
598	      );
599	    } catch {
600	      this.rowError.set({ id: person.id, message: `A statement could not be taken for ${person.name}.` });
601	    }
602	  }
603	
604	  protected edit(person: Person): void {
605	    this.rowError.set(null);
606	    this.editingId.set(person.id);
607	    this.editingVersion.set(person.version);
608	    this.name.set(person.name);
609	    this.grade.set(this.gradeOf(person));
610	    this.gradeFrom.set('');
611	    this.error.set(null);
612	  }
613	
614	  protected reset(): void {
615	    this.editingId.set(null);
616	    this.name.set('');
617	    this.grade.set('A');
618	    this.gradeFrom.set('');
619	    this.error.set(null);
620	  }
621	
622	  protected async submit(event: Event): Promise<void> {
623	    event.preventDefault();
624	    if (this.busy()) return;
625	    this.error.set(null);
626	    const sheet = this.session.sheetId();
627	    if (!sheet) return;
628	    const body = { name: this.name().trim(), grade: this.grade() };
629	    if (!body.name) {
630	      this.error.set('Type a name for the person.');
631	      return;
632	    }
633	    const id = this.editingId();
634	    const base = `/api/sheets/${encodeURIComponent(sheet)}/people`;
635	    this.busy.set(true);
636	    try {
637	      const saved = await firstValueFrom(
638	        id === null
639	          ? this.http.post<Person>(base, body)
640	          : this.http.put<Person>(`${base}/${id}`, {
641	              ...body,
642	              gradeFrom: this.gradeFrom().trim() || null,
643	              version: this.editingVersion(),
644	            }),
645	      );
646	      if (this.session.sheetId() !== sheet) return;
647	      this.people.update((list) =>
648	        id === null ? [...list, saved] : list.map((p) => (p.id === saved.id ? saved : p)),
649	      );
650	      this.reset();
651	    } catch (e) {
652	      if (id !== null && e instanceof HttpErrorResponse && e.status === 412) {
653	        await this.showCurrent(sheet, id, e.error as Person | null);
654	        this.error.set('Someone else saved this person since you opened the editor; their values are shown.');
655	      } else if (e instanceof HttpErrorResponse && e.status === 409) {
656	        this.error.set(`Another person on the sheet is already named ${body.name}.`);
657	      } else {
658	        this.error.set(id === null ? 'The person could not be added.' : 'The person could not be saved.');
659	      }
660	    } finally {
661	      this.busy.set(false);
662	    }
663	  }
664	
665	  /** Add a DRAFT claim for the named person, adding them (grade A) when the name is not on the
666	   *  sheet; their row and the claim then show. */
667	  protected async quickAdd(event: Event): Promise<void> {
668	    event.preventDefault();
669	    if (this.quickBusy()) return;
670	    this.quickError.set(null);
671	    const sheet = this.session.sheetId();
672	    if (!sheet) return;
673	    const name = this.quickName().trim();
674	    const amount = this.quickAmount().trim();
675	    if (!name) {
676	      this.quickError.set('Type a name for the claim.');
677	      return;
678	    }
679	    if (!AMOUNT.test(amount)) {
680	      this.quickError.set('Type an amount of 0.00 or more, with up to two decimals.');
681	      return;
682	    }
683	    this.quickBusy.set(true);
684	    try {
685	      const added = await firstValueFrom(
686	        this.http.post<{ person: Person; claim: Claim }>(
687	          `/api/sheets/${encodeURIComponent(sheet)}/quick-add`,
688	          { name, amount },
689	        ),
690	      );
691	      if (this.session.sheetId() !== sheet) return;
692	      this.people.update((list) =>
693	        list.some((p) => p.id === added.person.id)
694	          ? list.map((p) => (p.id === added.person.id ? added.person : p))
695	          : [...list, added.person],
696	      );
697	      this.claimSaved(added.claim);
698	      this.quickName.set('');
699	      this.quickAmount.set('');
700	    } catch (e) {
701	      this.quickError.set(
702	        e instanceof HttpErrorResponse && e.status === 409
703	          ? `A claim for ${name} could not be added: its date falls in a closed period or after they retired.`
704	          : `A claim for ${name} could not be added.`,
705	      );
706	    } finally {
707	      this.quickBusy.set(false);
708	    }
709	  }
710	
711	  /** After a refused stale save, show the person as stored now, in their row and in the editor,
712	   *  which then holds the version it shows. */
713	  private async showCurrent(sheet: string, id: number, current: Person | null): Promise<void> {
714	    if (!current) {
715	      const list = await firstValueFrom(
716	        this.http.get<Person[]>(`/api/sheets/${encodeURIComponent(sheet)}/people`),
717	      ).catch(() => []);
718	      current = list.find((p) => p.id === id) ?? null;
719	    }
720	    if (!current || this.session.sheetId() !== sheet) return;
721	    const now = current;
722	    this.people.update((list) => list.map((p) => (p.id === now.id ? now : p)));
723	    if (this.editingId() === now.id) {
724	      this.editingVersion.set(now.version);
725	      this.name.set(now.name);
726	      this.grade.set(this.gradeOf(now));
727	    }
728	  }
729	
730	  /** Read the sheet's people and claims; a response for an earlier load is dropped. */
731	  private async read(sheet: string, load: number): Promise<void> {
732	    const base = `/api/sheets/${encodeURIComponent(sheet)}`;
733	    const [list, claims] = await Promise.all([
734	      firstValueFrom(this.http.get<Person[]>(`${base}/people`)),
735	      firstValueFrom(this.http.get<Claim[]>(`${base}/claims`)),
736	    ]);
737	    if (this.session.loads() !== load) return;
738	    this.people.set(list);
739	    this.claims.set(claims);
740	  }
741	}
